    gap: 2px;
    background: #222529;
    border: 1px solid #3c3d40;
    border-radius: 8px;
    padding: 6px;
    margin-top: 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
    width: fit-content;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.3rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-btn:hover {
    background: #3a3b3f;
}

/* ── Message Input ── */
.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #2c2d30;
    background: #222529;
    flex-shrink: 0;
    align-items: flex-end;
}

.message-input {
    flex: 1;
    resize: none;
    background: #2c2d30;
    border: 1px solid #3c3d40;
    border-radius: 8px;
    padding: 10px 12px;
    color: #d1d2d3;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input:focus {
    border-color: #1d9bd1;
}

.message-input::placeholder {
    color: #717274;
}

.send-btn {
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.15s;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background: #148567;
}

.send-btn:disabled {
    background: #2c2d30;
    color: #717274;
    cursor: not-allowed;
}

/* ── Thread Panel ── */
.thread-panel {
    width: 25%;
    min-width: 280px;
    display: flex;
    flex-direction: column;
    background: #222529;
    overflow: hidden;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #2c2d30;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #fff;
}

.close-btn {
    background: none;
    border: none;
    color: #9ea0a5;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #3a3b3f;
    color: #fff;
}

.thread-root-quote {
    padding: 12px 16px;
    border-bottom: 1px solid #2c2d30;
    background: #2c2d30;
    flex-shrink: 0;
}

.thread-root-quote .author {
    font-size: 0.85rem;
}

.thread-root-quote p {
    margin: 4px 0 0;
    font-size: 0.88rem;
    color: #d1d2d3;
    line-height: 1.4;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-replies .message-bubble {
    padding: 6px 0;
}
"}

