toolArgs.file_text:
/* ── Layout Shell ── */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: #1a1d21;
    color: #d1d2d3;
}

/* ── Left Sidebar ── */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #19171d;
    border-right: 1px solid #2c2d30;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid #2c2d30;
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #fff;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    position: relative;
    border-left: 3px solid transparent;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #27242c;
}

.channel-item.active {
    background: #1164a3;
    border-left-color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #fff;
}

.channel-desc {
    font-size: 0.78rem;
    color: #9ea0a5;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #e01e5a;
    color: #fff;
    font-size: 0.72rem;
    font-weight: 700;
    padding: 2px 7px;
    border-radius: 10px;
    min-width: 20px;
    text-align: center;
}

/* ── Main Message Area ── */
.message-area {
    width: 55%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border-right: 1px solid #2c2d30;
    transition: width 0.2s ease;
}

.message-area.expanded {
    width: 80%;
    border-right: none;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #2c2d30;
    background: #1a1d21;
    flex-shrink: 0;
}

.message-header h2 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
    color: #fff;
}

.header-desc {
    font-size: 0.82rem;
    color: #9ea0a5;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 10px;
    color: #9ea0a5;
    font-size: 0.85rem;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #9ea0a5;
    font-size: 1.1rem;
}

/* ── Message Bubble ── */
.message-row {
    position: relative;
    padding: 6px 0;
}

.message-row:hover {
    background: rgba(255, 255, 255, 0.03);
    border-radius: 6px;
}

.message-bubble {
    position: relative;
    padding: 4px 8px;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.92rem;
    color: #fff;
}

.timestamp {
    font-size: 0.75rem;
    color: #717274;
}

.message-content {
    font-size: 0.93rem;
    line-height: 1.5;
    color: #d1d2d3;
    word-break: break-word;
}

/* ── Reactions ── */
.reaction-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    background: #2c2d30;
    border: 1px solid #3c3d40;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.82rem;
    cursor: default;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #3a3b3f;
}

/* ── Thread Link ── */
.thread-link {
    background: none;
    border: none;
    color: #1d9bd1;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 2px;
}

.thread-link:hover {
    text-decoration: underline;
}

/* ── Hover Actions ── */
.message-actions {
    position: absolute;
    top: -4px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #222529;
    border: 1px solid #3c3d40;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
    z-index: 5;
}

.action-btn {
    background: none;
    border: none;
    color: #d1d2d3;
    font-size: 0.8rem;
    padding: 4px 8px;
    border-radius: 4px;
    cursor: pointer;
    white-space: nowrap;
}

.action-btn:hover {
    background: #3a3b3f;
}

/* ── Emoji Picker ── */
.emoji-picker {
    display: flex;
    gap: 2px;
    background: #222529;
    border: 1px solid #3c3d40;
    border-radius: 8px;
    padding: 6px;
    margin-top: 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
    width: fit-content;
}

.emoji-btn {
