+    border-bottom: 1px solid #2c2d30;
+    background: #2c2d30;
+    flex-shrink: 0;
+}
+
+.thread-root-quote .author {
+    font-size: 0.85rem;
+}
+
+.thread-root-quote p {
+    margin: 4px 0 0;
+    font-size: 0.88rem;
+    color: #d1d2d3;
+    line-height: 1.4;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+}
+
+.thread-replies .message-bubble {
+    padding: 6px 0;
+}
+

